<script setup lang="ts">
import {contentSchema,type Content} from '#shared/content';
const props=defineProps<{kind:'news'|'alerts'}>();const alerts=props.kind==='alerts';
const {state,send}=usePortal();const requestFetch=useRequestFetch();
const records=ref<any[]>([]),users=ref<any[]>([]),draft=ref<any>(null),deliveries=ref<any[]>([]),review=ref<any>(null),preview=ref(false),busy=ref(false),error=ref(''),message=ref(''),search=ref(''),editorKey=ref(0),deleteConfirm=ref(false),uncertain=ref('');
const filteredUsers=computed(()=>users.value.filter(u=>(u.name+' '+(u.email||'')).toLowerCase().includes(search.value.toLowerCase())));
const locked=computed(()=>!!draft.value?.sent);const eligible=computed(()=>users.value.filter(u=>u.email&&(draft.value?.audience==='all'||draft.value?.userIds.includes(u.id))).length);
const counts=computed(()=>deliveries.value.reduce((out:Record<string,number>,r:any)=>{out[r.status]=(out[r.status]||0)+1;return out;},{}));
function selectRecipient(id:string,checked:boolean){if(!draft.value)return;draft.value.userIds=checked?[...new Set([...draft.value.userIds,id])]:draft.value.userIds.filter((value:string)=>value!==id);}
const date=(v:number)=>new Date(v).toLocaleString();
async function load(){records.value=await requestFetch<any[]>('/api/admin/'+props.kind);if(alerts)users.value=await requestFetch<any[]>('/api/admin/alerts/users');}
if(state.value?.user?.role==='admin')try{await load();}catch(e){error.value=errorText(e);}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function create(){draft.value={title:'',content:[{type:'paragraph',children:[]}] as Content,audience:'all',userIds:[]};reset();}
function reset(){editorKey.value++;preview.value=false;review.value=null;deleteConfirm.value=false;deliveries.value=[];uncertain.value='';search.value='';message.value='';}
async function open(row:any){reset();await run(async()=>{draft.value=await requestFetch('/api/admin/'+props.kind+'/detail',{query:{id:row.id}});editorKey.value++;if(draft.value.sent)await status();});}
async function status(){deliveries.value=await requestFetch<any[]>('/api/admin/alerts/status',{query:{id:draft.value.id}});}
async function save(){if(!draft.value.title.trim())throw new Error('Enter a '+(alerts?'subject.':'title.'));const parsed=contentSchema.safeParse(draft.value.content);if(!parsed.success)throw new Error('Write a message using the supported formatting (up to 40,000 characters).');draft.value=await send('admin/'+props.kind+'/save',draft.value);await load();}
async function reviewSend(){await save();review.value=await send('admin/alerts/preview',{id:draft.value.id});preview.value=true;}
async function sendAlert(){await send('admin/alerts/send',{id:draft.value.id,token:review.value.token});draft.value=await requestFetch('/api/admin/alerts/detail',{query:{id:draft.value.id}});review.value=null;await status();await load();message.value='Alert queued for delivery.';}
async function publish(value:boolean){if(value)await save();draft.value=await send('admin/news/publish',{id:draft.value.id,publish:value});await load();message.value=value?'News published.':'News returned to drafts.';}
async function remove(){await send('admin/'+props.kind+'/delete',{id:draft.value.id});draft.value=null;await load();message.value='Draft deleted.';}
async function retry(row:any,acknowledge=false){await send('admin/alerts/retry',{id:draft.value.id,recipientId:row.id,acknowledge});uncertain.value='';await status();}
watch(()=>JSON.stringify(draft.value),()=>{review.value=null;},{flush:'sync'});
</script>
<template><main v-if="state?.user?.role==='admin'" class="page communications-page"><NuxtLink to="/admin" class="inline-link">← Admin</NuxtLink><div class="page-title"><h1>{{alerts?'Email alerts':'News'}}</h1><CindorButton variant="solid" class="button primary" :disabled="busy" @click="create">{{alerts?'New alert':'New post'}}</CindorButton></div>
 <p class="muted">{{alerts?'Important notices sent by email to verified addresses.':'General updates for the portal. Publishing does not send email.'}}</p>
 <CindorAlert v-if="error" class="portal-alert" tone="danger">{{error}}</CindorAlert><p v-if="message" class="notice" role="status">{{message}}</p>
 <div class="communications-grid"><section class="panel communications-list"><h2>{{alerts?'Drafts & history':'Posts'}}</h2><p v-if="!records.length" class="muted">{{alerts?'No alerts yet.':'No posts yet.'}}</p><ul class="plain-list"><li v-for="row in records" :key="row.id"><CindorButton variant="ghost" class="record-button" :disabled="busy" :aria-current="draft?.id===row.id?'true':undefined" @click="open(row)"><strong>{{row.title}}</strong><small>{{row.sent?'Submitted '+date(row.sent):row.published?'Published '+date(row.published):'Draft'}}</small></CindorButton></li></ul></section>
 <section v-if="draft" class="panel communications-compose"><div class="section-heading"><h2>{{locked?'Alert history':draft.published?'Edit post':'Draft'}}</h2><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="draft=null">Close</CindorButton></div>
 <template v-if="!locked"><label for="communication-title">{{alerts?'Subject':'Title'}}</label><input id="communication-title" v-model="draft.title" maxlength="200" :disabled="busy"><label>Message</label><ContentEditor :key="editorKey" v-model="draft.content" :disabled="busy"/>
 <fieldset v-if="alerts" :disabled="busy"><legend>Recipients</legend><CindorRadio class="choice" name="audience" value="all" :checked="draft.audience==='all'" :disabled="busy" @update:checked="$event && (draft.audience='all')">All active users</CindorRadio><CindorRadio class="choice" name="audience" value="selected" :checked="draft.audience==='selected'" :disabled="busy" @update:checked="$event && (draft.audience='selected')">Selected users</CindorRadio><template v-if="draft.audience==='selected'"><label for="recipient-search">Find a user</label><CindorInput id="recipient-search" v-model="search" type="search" placeholder="Search by name or email"/><div class="recipient-picker"><CindorCheckbox v-for="u in filteredUsers" :key="u.id" class="choice" :model-value="draft.userIds.includes(u.id)" :disabled="busy" @update:model-value="selectRecipient(u.id,$event)">{{u.name}} · {{u.email||'No verified email — will be skipped'}}</CindorCheckbox></div></template><p class="small muted">{{eligible}} eligible recipients</p></fieldset>
 <div class="actions"><CindorButton variant="ghost" class="button" :disabled="busy" @click="run(async()=>{await save();message='Saved.';})">{{draft.published?'Save changes':'Save draft'}}</CindorButton><CindorButton variant="ghost" class="button" :disabled="busy" @click="preview=!preview">{{preview?'Hide preview':'Preview'}}</CindorButton><CindorButton variant="solid" v-if="alerts" class="button primary" :disabled="busy||!eligible||!state.configured.email" @click="run(reviewSend)">Review recipients & send</CindorButton><CindorButton variant="solid" v-else class="button primary" :disabled="busy" @click="run(async()=>{await save();preview=true;})">Review for publication</CindorButton></div>
 <p v-if="alerts&&!state.configured.email" class="notice">Configure email delivery before sending.</p></template>
 <article v-if="preview||locked" class="content-preview"><p class="eyebrow">{{locked?'Submitted content':'Preview'}}</p><h2>{{draft.title}}</h2><ContentView :content="draft.content"/><CindorButton variant="solid" v-if="!alerts&&!draft.published" class="button primary" :disabled="busy" @click="run(()=>publish(true))">Publish news</CindorButton></article>
 <section v-if="review" class="send-review"><h3>Send to {{review.recipients.length}} {{review.recipients.length===1?'user':'users'}}</h3><ul class="review-recipients"><li v-for="u in review.recipients" :key="u.id">{{u.name}} · {{u.email}}</li></ul><p v-if="review.skipped.length">{{review.skipped.length}} skipped — no verified email: {{review.skipped.map((u:any)=>u.name).join(', ')}}</p><CindorButton variant="solid" class="button primary" :disabled="busy||!review.recipients.length" @click="run(sendAlert)">Send to {{review.recipients.length}} {{review.recipients.length===1?'user':'users'}}</CindorButton><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="review=null">Cancel</CindorButton></section>
 <section v-if="locked"><div class="section-heading"><h3>Delivery status</h3><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="run(status)">Refresh</CindorButton></div><p class="small muted">Sent means accepted by the mail server, not confirmed inbox delivery.</p><div class="delivery-counts"><span v-for="(count,label) in counts" :key="label">{{count}} {{label}}</span></div><ul class="plain-list"><li v-for="row in deliveries" :key="row.id"><div><strong>{{row.name||'Former user'}}</strong><small>{{row.address||'No verified email'}} · {{row.status}}</small><p v-if="row.error" class="small">{{row.error}}</p><template v-if="uncertain===row.id"><p class="notice">This person may already have received the alert. Retrying could send a duplicate.</p><CindorButton variant="ghost" class="button" :disabled="busy" @click="run(()=>retry(row,true))">Retry despite duplicate risk</CindorButton><CindorButton variant="ghost" class="text-button" @click="uncertain=''">Cancel</CindorButton></template></div><CindorButton variant="ghost" v-if="row.status==='failed'" class="text-button" :disabled="busy" @click="run(()=>retry(row))">Retry</CindorButton><CindorButton variant="ghost" v-if="row.status==='uncertain'&&uncertain!==row.id" class="text-button" :disabled="busy" @click="uncertain=row.id">Review retry</CindorButton></li></ul></section>
 <div v-if="!locked&&draft.id" class="draft-maintenance"><CindorButton variant="ghost" v-if="draft.published" class="text-button" :disabled="busy" @click="run(()=>publish(false))">Unpublish</CindorButton><CindorButton variant="ghost" v-else class="text-button" :disabled="busy" @click="deleteConfirm=true">Delete draft…</CindorButton><div v-if="deleteConfirm"><p>Delete this draft?</p><CindorButton variant="ghost" class="button danger" :disabled="busy" @click="run(remove)">Delete draft</CindorButton><CindorButton variant="ghost" class="text-button" @click="deleteConfirm=false">Cancel</CindorButton></div></div>
 </section><section v-else class="panel muted">{{alerts?'Create an alert or select a draft or sent notice.':'Create a post or select one to edit.'}}</section></div></main></template>
